// Wan2GP / Qwen Image 2.1 payload builder.
// Reference mode is "I" (references are people/objects), NOT "KI": with "K" the engine
// re-derives the output canvas from reference #1's aspect ratio (wgp.py:7866-7872 +
// utils.calculate_new_dimensions) and the poster would stop being 1:1.
// Refs are sent in the same order the prompt numbers them as <image1>, <image2>, ...
const HTTP_URL = new RegExp('^https?://', 'i');
const MAX_REFS = 4;                 // model supports 10; posters rarely benefit from more
const parsed = $('Parse Output').first().json;
const blog = parsed.blog_data || {};
const prompt = (parsed.image_prompt || 'a modern dental clinic photograph').trim();

const normalizeRefs = (urls) => {   // -> string[]
  const out = [];
  const seen = new Set();
  for (const raw of (Array.isArray(urls) ? urls : [urls])) {
    if (typeof raw !== 'string') continue;
    const u = raw.trim();
    if (!HTTP_URL.test(u)) continue;   // Wan2GP fetches with urllib: http(s) only
    const key = u.toLowerCase();
    if (seen.has(key)) continue;        // de-dupe
    seen.add(key);
    out.push(u);
    if (out.length >= MAX_REFS) break;  // order is significant -> truncate, never shuffle
  }
  return out;
};

const refs = normalizeRefs(parsed.reference_image_urls);
const refMode = refs.length > 0 ? 'I' : '';  // '' => pure text-to-image

// Wan2GP /n8n/sync contract: only "I" in video_prompt_type actually enables image_refs.
// image_prompt_type stays empty: Qwen 2.1 has no start/end frame modes, references only.
const body = {
  prompt: prompt,
  model_type: 'qwen_image_21_7B',
  resolution: '1024x1024',                    // multiples of 32 (vae_block_size); Instagram 1:1
  num_inference_steps: 40,                    // model default = recommended (40 @ ~1024px)
  image_prompt_type: '',
  video_prompt_type: refMode,
  image_refs: refs,
  custom_settings: { qwen21_kv_cache: 'Disabled', rgba: 'Disabled' },
};

return { json: { body: body, image_prompt: prompt, reference_image_urls: refs, ref_mode: refMode === 'I' ? 'references' : 'text-only', blog_data: blog, caption: parsed.caption || '' } };

extractImageCode:
// Wan2GP returns { url }; "Download Image" turns that into binary.data.
// Re-attach context from Parse Output (HTTP nodes drop upstream JSON) and keep the
// existing skip_upload contract so "Process Each Blog" keeps looping on failure.
const parsed = $('Parse Output').first().json;
const blog = parsed.blog_data || {};
const caption = parsed.caption || '';
const refUrls = parsed.reference_image_urls || [];
const src = $input.first() || {};
const bin = src.binary && src.binary.data;
const resp = $('Wan2GP Qwen 2.1').first().json || {};
const err = resp.error || (resp.message ? String(resp.message).slice(0, 400) : '');

if (!bin || !bin.data) {
  console.error('No image for blog id=' + blog.id + ' err=' + err + ' - emitting skip_upload to keep SplitInBatches loop alive');
  return { json: { error: 'No image generated', error_detail: err || 'Wan2GP returned no url', blog_data: blog, caption: caption, reference_image_urls: refUrls, skip_upload: true, website_url: blog.Website_url || '', wp_user: blog.wp_user || '', app_password: blog.app_password || '', fileName: 'failed-' + (blog.id || Date.now()) + '.jpg' } };
}

const fileName = 'social-post-' + Date.now() + '.jpg';   // server image codec is jpeg_95 -> .jpg
return [{ json: { success: true, mimeType: bin.mimeType || 'image/jpeg', source_url: resp.url || '', blog_data: blog, caption: caption, website_url: blog.Website_url || '', wp_user: blog.wp_user || '', app_password: blog.app_password || '', fileName: fileName, reference_image_urls: refUrls }, binary: { data: { data: bin.data, mimeType: bin.mimeType || 'image/jpeg', fileName: fileName } } }];
